pragma solidity ^0.8.0;

contract VulnerableToken {
    mapping(address => uint256) public balances;
    event Transfer(address indexed from, address indexed to, uint256 amount);

    function transfer(address to, uint256 amount) public returns (bool) {
        require(balances[msg.sender] >= amount, "Insufficient");
        require(to != address(0), "Zero address");

        // VULNERABLE: interaction before effects
        (bool success, ) = to.call{value: 0}("");

        // Balance update AFTER external call = reentrancy window
        balances[msg.sender] -= amount;
        balances[to] += amount;

        emit Transfer(msg.sender, to, amount);
        return true;
    }
}

import json, base64
from flask import Flask, request, jsonify

app = Flask(__name__)

def check_auth(required_role=None):
    auth = request.headers.get('Authorization')
    if not auth:
        return None, ('Unauthorized', 401)
    try:
        token_data = json.loads(base64.b64decode(auth.split(' ')[1]))
    except:
        return None, ('Invalid token', 401)

    # No signature check! No expiry check!
    if required_role and token_data.get('role') != required_role:
        return None, ('Forbidden', 403)
    return token_data, None

@app.route('/users/<int:uid>', methods=['DELETE'])
def delete_user(uid):
    user, err = check_auth(required_role='admin')
    if err: return jsonify({'error': err[0]}), err[1]
    return jsonify({'deleted': uid}), 200

